examples.template:
Column {
    MonarchButton(text = {{trigger}}, onClick = { open = true })
}
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = {{title}}, description = {{description}}) {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchMethodBadge(method = {{request.method}})
                MonarchText(text = {{request.path}}, style = MonarchTextStyle.Code)
            }
            MonarchDescriptionList(
                items = listOf(
                    MonarchDescriptionItem("Status", {{request.status}}.toString()) {
                        Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                            MonarchBadge(text = {{request.status}}.toString(), tone = statusTone({{request.status}}))
                            MonarchText(text = {{request.errorCode}}, style = MonarchTextStyle.Code)
                        }
                    },
                    MonarchDescriptionItem("Request ID", {{request.id}}, copyable = true),
                    MonarchDescriptionItem(
                        "Time",
                        DateUtils.getRelativeTimeSpanString(now - {{request.minutesAgo}} * 60_000L, now, DateUtils.MINUTE_IN_MILLIS).toString(),
                    ),
                    MonarchDescriptionItem("Duration", {{request.durationMs}}.toString() + " ms"),
                    MonarchDescriptionItem({{fields.0.label}}, {{fields.0.value}}),
                    MonarchDescriptionItem({{fields.1.label}}, {{fields.1.value}}, copyable = true, copyValue = {{fields.1.copyValue}}) {
                        MonarchText(text = {{fields.1.value}}, style = if ({{fields.1.mono}}) MonarchTextStyle.Code else MonarchTextStyle.Body)
                    },
                    MonarchDescriptionItem({{fields.2.label}}, {{fields.2.value}}),
                ),
            )
        }
    }
}

examples.setupTemplate:
var open by rememberSaveable { mutableStateOf(true) }
val now = remember { System.currentTimeMillis() }
val statusTone: (Int) -> MonarchTone = { status ->
    when (status / 100) {
        2 -> MonarchTone.Success
        3 -> MonarchTone.Info
        4 -> MonarchTone.Warning
        else -> MonarchTone.Danger
    }
}

