    MonarchBottomSheet(onDismissRequest = { open = false }, title = "Request details", description = "Request and response bodies are not stored.") {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchMethodBadge(method = "POST")
                MonarchText(text = "/v1/orders", style = MonarchTextStyle.Code)
            }
            MonarchDescriptionList(
                items = listOf(
                    MonarchDescriptionItem("Status", 429.toString()) {
                        Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                            MonarchBadge(text = 429.toString(), tone = statusTone(429))
                            MonarchText(text = "rate_limited", style = MonarchTextStyle.Code)
                        }
                    },
                    MonarchDescriptionItem("Request ID", "req_7f3a2c90d1", copyable = true),
                    MonarchDescriptionItem(
                        "Time",
                        DateUtils.getRelativeTimeSpanString(now - 4 * 60_000L, now, DateUtils.MINUTE_IN_MILLIS).toString(),
                    ),
                    MonarchDescriptionItem("Duration", 84.toString() + " ms"),
                    MonarchDescriptionItem("Credential", "Reporting job"),
                    MonarchDescriptionItem("Origin", "https://shop.example.com", copyable = true, copyValue = "https://shop.example.com") {
                        MonarchText(text = "https://shop.example.com", style = if (true) MonarchTextStyle.Code else MonarchTextStyle.Body)
                    },
                    MonarchDescriptionItem("Units", "1 request"),
                ),
            )
        }
